#  사후(결과 본 뒤): 체육 변수 역방향(걷기·마을체육시설 −, 가설 +)·창별 불안정 → P1 민감도 전용 변수 추가 · P2 체육 변수 단독(+강제) · P3 인구밀도(log) · P4 지역 간/지역 내 분해 · P10 체육 4종만(+강제)
#  사전지정(설계 메모 11/18): P5 2020-21 제외 · P6 2019-24만(대상 확대 이후) · P7 제조업 종사자 비중 추가(2017-24, 세종 원천 빈칸 → 결과 NA) · P8 인구 기반 성×연령 기대치(off_sens)
suppressPackageStartupMessages({library(INLA);library(sf);library(jsonlite)})
TAG<-"SCRN";VER<-"std3";inla.setOption(num.threads="1:1")
OUTD<-file.path("..","04_분석",TAG);RES<-file.path(OUTD,paste0("results_",VER))
SHP<-Sys.getenv("ST_SHP",file.path(normalizePath(file.path(dirname(sub("--file=","",grep("--file=",commandArgs(),value=TRUE))),"..")),"data","boundary","final.shp"))
S<-fromJSON(file.path(OUTD,"config_SCRN_std3.json"),simplifyVector=TRUE)
DD<-read.csv(file.path(OUTD,"panel_SCRN_std3.csv"),fileEncoding="UTF-8-BOM",stringsAsFactors=FALSE);DD$fbd_region<-enc2utf8(DD$fbd_region)
G<-st_read(SHP,quiet=TRUE);G$region<-enc2utf8(G$region);g<-inla.read.graph(Sys.getenv("ST_GRAPH"));stopifnot(g$n==nrow(G))
DD$area<-match(DD$fbd_region,G$region);DD$time<-DD$year-min(DD$year)+1;DD$yiid<-DD$time;DD$obs<-seq_len(nrow(DD))
FORCED<-S$forced;HYP<-as.character(S$sets_after_vif$S1_narrative_full);MAIN<-unique(c(HYP,FORCED))
pc<-list(prec=list(prior="pc.prec",param=c(0.5,0.01)),phi=list(prior="pc",param=c(0.5,2/3)));pcp<-list(prec=list(prior="pc.prec",param=c(0.5,0.01)))
z<-function(x)(x-mean(x,na.rm=TRUE))/sd(x,na.rm=TRUE)
fit<-function(vars,d=DD,off="off"){d$OFF<-d[[off]];f<-as.formula(paste("cases ~ 1 +",paste(sprintf("`%s`",vars),collapse="+"),"+ f(area,model='bym2',graph=g,scale.model=TRUE,constr=TRUE,hyper=pc) + f(time,model='rw1',scale.model=TRUE,hyper=pcp) + f(yiid,model='iid',hyper=pcp) + f(obs,model='iid',hyper=pcp) + offset(OFF)"))
  m<-inla(f,family="binomial",data=d,Ntrials=d$Ntr,control.fixed=list(mean=0,prec=4,mean.intercept=0,prec.intercept=0.001),control.compute=list(waic=TRUE),control.predictor=list(link=1),control.inla=list(control.vb=list(emergency=50)))
  pp<-m$summary.fitted.values$mean[seq_len(nrow(d))];stopifnot(all(pp>0&pp<1));m}   # 이항 적합값 = 확률 척도(link=1: 결과 NA 행도 확률 척도로 — 11/19 P5에서 NA 행이 선형예측자 척도로 나와 stopifnot이 잡음)
out<-NULL
add<-function(an,m,vs){fx<-m$summary.fixed;for(v in vs){if(!v%in%rownames(fx))next;r<-fx[v,];out<<-rbind(out,data.frame(analysis=an,cov=v,OR=round(exp(r$mean),4),lo=round(exp(r$`0.025quant`),4),hi=round(exp(r$`0.975quant`),4),cred=(exp(r$`0.025quant`)>1|exp(r$`0.975quant`)<1),WAIC=round(m$waic$waic,1)))};cat(an,"done\n");write.csv(out,file.path(RES,"S46_scrn_posthoc.csv"),row.names=FALSE)}
PA<-c("ext__walking_rate","moderate_pa_rate","ext__public_sport_fac_per100k","ext__village_sport_fac_per100k");REP<-unique(c(PA,HYP))
DD$popdens_log<-z(log(DD$population/(DD$area_m2/1e6)))
BWV<-c(PA,"ext__living_alone_elderly","tertiary_educated_share")
for(v in BWV){m<-ave(DD[[v]],DD$fbd_region);DD[[paste0(v,"__B")]]<-(m-mean(m))/sd(m);w<-DD[[v]]-m;DD[[paste0(v,"__W")]]<-w/sd(w)}
SENS<-intersect(c("ext__medicaid1_share","genhosp_per100k"),names(DD))
add("P0_main",fit(MAIN),REP)
add("P1_plus_sensitivity_vars",fit(c(MAIN,SENS)),c(PA,SENS))
for(v in PA)add(paste0("P2_alone_",v),fit(c(v,FORCED)),v)
add("P3_plus_popdens",fit(c(MAIN,"popdens_log")),c(PA,"popdens_log"))
add("P4_between_within",fit(c(setdiff(MAIN,BWV),paste0(BWV,"__B"),paste0(BWV,"__W"))),c(paste0(BWV,"__B"),paste0(BWV,"__W")))
add("P10_PA_only",fit(c(PA,FORCED)),PA)
d5<-DD;d5$cases[d5$year%in%2020:2021]<-NA;add("P5_excl_2020_2021",fit(MAIN,d5),REP)
d6<-DD[DD$year>=2019,];d6$time<-d6$year-min(d6$year)+1;d6$yiid<-d6$time;d6$obs<-seq_len(nrow(d6));for(v in MAIN)d6[[v]]<-z(d6[[v]]);add("P6_2019_2024_only",fit(MAIN,d6),REP)
MF<-read.csv(file.path(OUTD,"EXT_manufacturing_share_2017_24.csv"),fileEncoding="UTF-8-BOM",stringsAsFactors=FALSE);MF$fbd_region<-enc2utf8(MF$fbd_region)
d7<-DD[DD$year>=2017,];d7$manufacturing_share<-MF$manufacturing_share[match(paste(d7$year,d7$fbd_region),paste(MF$year,MF$fbd_region))]
d7$cases[is.na(d7$manufacturing_share)]<-NA;d7$manufacturing_share[is.na(d7$manufacturing_share)]<-mean(d7$manufacturing_share,na.rm=TRUE);d7$manufacturing_share<-z(d7$manufacturing_share)
d7$time<-d7$year-min(d7$year)+1;d7$yiid<-d7$time;d7$obs<-seq_len(nrow(d7));for(v in MAIN)d7[[v]]<-z(d7[[v]])
add("P7a_2017_2024_main",fit(MAIN,d7),REP);add("P7b_2017_2024_plus_manufacturing",fit(c(MAIN,"manufacturing_share"),d7),c(REP,"manufacturing_share"))
add("P8_population_based_age_sex_E",fit(MAIN,DD,"off_sens"),REP)
print(out)
